fn main(){let path=std::env::var("VIDEOKADR_EXPORT_DOCUMENTS").unwrap();let input:serde_json::Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let cases=input["cases"].as_array().unwrap().iter().map(|document|{let bytes=serde_json::to_vec(document).unwrap();let parsed=filmcraft_project::gtemplate::GraphicsTemplate::from_bytes(&bytes);assert!(parsed.is_ok(),"{} {:?}",document["id"],parsed.err());let parsed=parsed.unwrap();serde_json::json!({"id":parsed.id,"accepted":true,"layers":parsed.layers.len(),"controls":parsed.controls.len()})}).collect::<Vec<_>>();println!("{}",serde_json::json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}